// The tag of ble-tx-poc-gen: one small link layer for several sensors, I2C or SPI, between the sensor and the AdvData of
// ble-tx-tag-8's packet (docs/Senseworks/TX_POC_GEN.md). A state machine with no processor and no memory: what differs
// from sensor to sensor is a table of constants (verilog/tag_profiles.v, generated by scripts/senseworks/tag_profile.py),
// chosen by the pins sel; the two bytes kept go in the packet as read, and the gateway converts them.
//
// All the state is one counter of ticks, t. A tick is 32.768 kHz: clk itself on the ASIC (TICK_DIV = 1), one clk in
// TICK_DIV on the FPGA (488: 16 MHz / 488 = 32.787 kHz). The last 2^12 ticks of a period run the table, 1024 slots of 4
// ticks each, one bit on the bus per slot, so SCL runs at 8.2 kHz; the wrap is tx_start. What a slot does (its code):
//   code[2] = 1   a bit: SCL pulsed; code[0]: SDA low; code[1]: SDA read into sensor_r, with SCL high
//   code[1:0], else   01 START, 10 STOP, 00 nothing
// SPI, on the same pins: SCLK on scl, SIO on sda, the waveform of I2C (SCLK high at rest, data changing with it low), and
// cs_n low from START to STOP. Three wires: the sensor drives SIO after a read command, so SDA is released once SCLK has
// risen, before it falls, when the sensor may start. cpol0: SCLK low at rest, SPI mode 0.
// Nothing waits for the bus: it cannot hang. The times are fixed, the maximum of each sensor's conversion.
//   - No sensor: SDA stays at the pull-up, sensor_r reads 0xFFFF, which none of these sensors' readings can be (their low
//     bits are 0) but the TMP114's, whose last unit of -0.0078 degC it would take for no sensor.
//   - A reset in the middle of a frame: every event configures the sensor again and the frames recover the bus: at most
//     one wrong packet, then right.
// The period, start to start, is exact in ticks: 2^(11+rate) (rate 1..7: 125 ms to 8 s, rate 0: off, nothing on the bus or
// on the air), less advDelay, 0 to 255 ticks (0 to 7.8 ms, within the Core's 0 to 10 ms, Core 6.1, Vol 6 Part B
// 4.4.2.2): an 8-bit LFSR stepped once per event, XOR AdvA's first byte. The conversion happens within the period.
// test_mode (the FPGA's PER measurements; tied to 0 on the chip): a counter in the packet, nothing on the bus; rate 0
// clears it. The ASIC's clock switch to 16 MHz for the packet is not in this core (tag_chip.v).

`define KEEP_FOR_DBG (*mark_debug="true",DONT_TOUCH="TRUE"*)

`timescale 1ns / 1ps
module tag_fsm #
(
  parameter integer TICK_DIV = 488,       // clk clocks per tick; 1: every clock is a tick
  parameter integer BCH_T = 8,            // passed to btle_tx
  parameter integer ADV_ADDRESS_OTP = 0,  // 1: AdvA from six eFuse blocks, passed to btle_tx
  parameter [47:0] ADV_ADDRESS = 48'hC10203040506,  // a random static address (two top bits 11): TxAdd = 1
  parameter [15:0] COMPANY_ID = 16'hFFFF, // passed to btle_tx
  parameter [5:0] CHANNEL = 6'd37
) (
  input  wire clk,
  input  wire rst,

  input  wire [2:0] rate,                 // static
  input  wire [1:0] sel,                  // the sensor, static
  input  wire test_mode,

  // the bus: scl_oe, sda_oe: pull the open-drain pin low
  input  wire sda_i,
  output reg  scl_oe,
  output reg  sda_oe,
  output wire cs_n,

  // ADV_ADDRESS_OTP = 1: passed to btle_tx
  input  wire [47:0] adv_address_otp_prog,
  output wire adv_address_otp_ready,

  // to the radio
  output wire signed [7:0] i,
  output wire signed [7:0] q,
  output wire iq_valid,
  output wire iq_valid_last,

  // btle_tx's debug outputs
  output wire phy_bit,
  output wire phy_bit_valid,
  output wire phy_bit_valid_last,
  output wire bit_upsample,
  output wire bit_upsample_valid,
  output wire bit_upsample_valid_last,
  output wire signed [15:0] bit_upsample_gauss_filter,
  output wire bit_upsample_gauss_filter_valid,
  output wire bit_upsample_gauss_filter_valid_last,

  // the state, for the controller's status registers
  output wire tx_start,
  output wire [15:0] sensor,              // as read: the first bit in [15]
  output wire [47:0] adv_address_sent
);

`KEEP_FOR_DBG reg [17:0] t;
reg [7:0] lfsr;
reg [15:0] sensor_r;
reg cs_low;

wire tick;
wire off = (rate == 3'd0);
wire [1:0] phase = t[1:0];
wire [9:0] slot = t[11:2];
wire wrap = &t;
wire measuring = &t[17:12] && !test_mode && !off;

wire [2:0] table_code;
wire spi, cpol0;
tag_profiles tag_profiles_i (
  .sel(sel),
  .slot(slot),
  .code(table_code),
  .spi(spi),
  .cpol0(cpol0)
);

wire [2:0] code = table_code & {3{measuring}};
wire is_bit = code[2];
wire is_start = !code[2] && code[0];
wire is_stop = !code[2] && code[1];
wire low_phase = (phase[1] == phase[0]);  // a bit: SCL low in phases 3 and 0, high in 1 and 2
wire scl_low_i2c = (is_start && (phase == 2'd3)) || (is_stop && (phase == 2'd0)) || (is_bit && low_phase);
wire scl_low = cpol0 ? !(is_bit && !low_phase) : scl_low_i2c;
wire sda_low = (!spi && ((is_start && (phase != 2'd0)) || (is_stop && !phase[1]))) ||  // SPI: SIO is left alone around CS_n
               (is_bit && code[0] && !(spi && phase[1]));  // SPI: released once SCLK has risen
wire sample = is_bit && code[1] && (phase == 2'd2);

// what t restarts from: the bits above t[7:0] leave 2^(11+rate) ticks to the wrap
wire [5:0] t_top = (rate == 3'd2) ? 6'b111110 :   // 250 ms
                   (rate == 3'd3) ? 6'b111100 :   // 500 ms
                   (rate == 3'd4) ? 6'b111000 :   // 1 s
                   (rate == 3'd5) ? 6'b110000 :   // 2 s
                   (rate == 3'd6) ? 6'b100000 :   // 4 s
                   (rate == 3'd7) ? 6'b000000 :   // 8 s
                                    6'b111111;    // 125 ms, and off
wire [9:0] t_high = {t_top, 4'd0};

assign tx_start = wrap && tick && !off;
assign cs_n = !(spi && cs_low);

always @ (posedge clk) begin
  if (rst || off) begin
    t <= {t_high, 8'd0};
  end else if (tick) begin
    if (wrap) begin
      t <= {t_high, lfsr ^ adv_address_sent[7:0]};
    end else begin
      t <= t + 1'b1;
    end
  end
  if (rst) begin
    lfsr <= 8'd0;
    scl_oe <= 1'b0;
    sda_oe <= 1'b0;
    cs_low <= 1'b0;
  end else if (tick) begin
    if (wrap) lfsr <= {lfsr[6:0], lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3] ^ (lfsr[6:0] == 7'd0)};  // 256 states, none stuck
    scl_oe <= scl_low;
    sda_oe <= sda_low;
    cs_low <= (code != 3'd0) && !is_stop;
  end
  if (test_mode && off) begin
    sensor_r <= 16'd0;
  end else if (tick) begin
    if (sample) sensor_r <= {sensor_r[14:0], sda_i};
    else if (test_mode && wrap) sensor_r <= sensor_r + 1'b1;
  end
end

generate
if (TICK_DIV > 1) begin : gen_tick_divider
  localparam integer DIV_BITS = $clog2(TICK_DIV);
  localparam integer DIV_LAST_INT = TICK_DIV - 1;
  localparam [(DIV_BITS-1):0] DIV_LAST = DIV_LAST_INT[(DIV_BITS-1):0];
  reg [(DIV_BITS-1):0] tick_count;
  always @ (posedge clk) begin
    if (rst || (tick_count == DIV_LAST)) begin
      tick_count <= {DIV_BITS{1'b0}};
    end else begin
      tick_count <= tick_count + 1'b1;
    end
  end
  assign tick = (tick_count == DIV_LAST);
end else begin : gen_no_tick_divider
  assign tick = 1'b1;
end
endgenerate

assign sensor = sensor_r;

wire [3:0] btle_tx_tap_index = 4'd15;     // GAUSS_TABLE = 1: its taps are fixed
wire [15:0] btle_tx_tap_value = 16'd0;

btle_tx #(
  .GAUSS_TABLE(1),
  .ADV_ADDRESS_OTP(ADV_ADDRESS_OTP),
  .COMPANY_ID(COMPANY_ID),
  .BCH_T(BCH_T),
  .SENSOR_BYTES(2)
) btle_tx_i (
  .clk(clk),
  .rst(rst),

  .gauss_filter_tap_index(btle_tx_tap_index),
  .gauss_filter_tap_value(btle_tx_tap_value),

  .cos_table_write_address(11'd0),
  .cos_table_write_data(8'd0),
  .sin_table_write_address(11'd0),
  .sin_table_write_data(8'd0),

  .preamble(8'hAA),
  .access_address(32'h8E89BED6),
  .crc_state_init_bit(24'h555555),
  .crc_state_init_bit_load(tx_start),
  .channel_number(CHANNEL),
  .channel_number_load(tx_start),

  .adv_address(ADV_ADDRESS),
  .tx_add(1'b1),
  .sensor({sensor_r[7:0], sensor_r[15:8]}),  // the byte read first, first on the air

  .tx_start(tx_start),

  .adv_address_otp_prog(adv_address_otp_prog),
  .adv_address_otp_ready(adv_address_otp_ready),
  .adv_address_sent(adv_address_sent),

  .i(i),
  .q(q),
  .iq_valid(iq_valid),
  .iq_valid_last(iq_valid_last),

  .phy_bit(phy_bit),
  .phy_bit_valid(phy_bit_valid),
  .phy_bit_valid_last(phy_bit_valid_last),

  .bit_upsample(bit_upsample),
  .bit_upsample_valid(bit_upsample_valid),
  .bit_upsample_valid_last(bit_upsample_valid_last),

  .bit_upsample_gauss_filter(bit_upsample_gauss_filter),
  .bit_upsample_gauss_filter_valid(bit_upsample_gauss_filter_valid),
  .bit_upsample_gauss_filter_valid_last(bit_upsample_gauss_filter_valid_last)
);

endmodule
